//Es la hija de Dispositivo, implementa Controlable, Alertable y Detectar Movimiento
public class CamaraSeguridad extends Dispositivo implements Controlable, Alertable, DetectorMovimiento {

    // Constructor vacio
    public CamaraSeguridad() {
        super();
    }


    // Constructor completo
    public CamaraSeguridad(String codigo, Oficina oficina, double potenciaNominal) {
        super(codigo, oficina, potenciaNominal);
    }


    // Encender la maquina
    @Override
    public boolean encender() {

        if (encendido) {
            return false;
        }

        encendido = true;
        return true;
    }


    // Apagar la maquina
    @Override
    public boolean apagar() {

        if (!encendido) {
            return false;
        }

        encendido = false;
        return true;
    }


    // Registrar movimiento. COn la hora devuelve los codigos de alerta

    @Override
    public int registrarMovimiento(int horaSimulacion) {

        if (!encendido) {
            return -1;
        }

        if (horaSimulacion < 0) {
            return -1;
        }

        // Obtiene la hora del dia
        int horaDia = horaSimulacion % 24;

        // Antes de las 7 o desde las 19
        if (horaDia < 7 || horaDia >= 19) {
            return 2;
        }

        // Dentro del horario laboral
        return 0;
    }


    // Generar alerta
    @Override
    public Alerta generarAlerta(int codigo, Severidad severidad, int horaSimulacion) {

        if (severidad == null || codigo <= 0 || horaSimulacion < 0) {
            return null;
        }

        int horaDia = horaSimulacion % 24;

        String mensaje = "Movimiento detectado fuera del horario laboral a las " + horaDia + ":00 por la camara " + this.codigo;

        return new Alerta(codigo, this, horaSimulacion, severidad, mensaje);
    }


    // Calcular consumo por hora

    @Override
    public double calcularConsumoHora() {

        if (!encendido) {
            return 0;
        }

        return potenciaNominal / 1000.0;
    }


    // toString

    @Override
    public String toString() {
        return super.toString() + "\nTipo: Camara de Seguridad";
    }
}
